#!/app/.venv/bin/python
import json
from pathlib import Path

import numpy as np
import pandas as pd
import stan


BASE = Path("/app")

STAN_CODE = r'''
functions {
  matrix cov_ard_sqexp(matrix X, vector rho, real alpha, real jitter) {
    int N = rows(X);
    int D = cols(X);
    matrix[N, N] K;

    for (i in 1:N) {
      K[i, i] = square(alpha) + jitter;
      for (j in (i + 1):N) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X[j, d]) / rho[d];
          s += t * t;
        }
        K[i, j] = square(alpha) * exp(-0.5 * s);
        K[j, i] = K[i, j];
      }
    }
    return K;
  }

  matrix cross_cov_ard(matrix X, matrix X_new, vector rho, real alpha) {
    int N = rows(X);
    int M = rows(X_new);
    int D = cols(X);
    matrix[N, M] Kx;
    for (i in 1:N) {
      for (j in 1:M) {
        real s = 0;
        for (d in 1:D) {
          real t = (X[i, d] - X_new[j, d]) / rho[d];
          s += t * t;
        }
        Kx[i, j] = square(alpha) * exp(-0.5 * s);
      }
    }
    return Kx;
  }
}

data {
  int<lower=1> N;
  int<lower=1> D;
  matrix[N, D] X;
  int<lower=1> P;
  matrix[N, P] H;
  vector[N] y;
  real<lower=0> jitter;

  int<lower=0> N_new;
  matrix[N_new, D] X_new;
  matrix[N_new, P] H_new;
}

parameters {
  vector[P] beta;
  real<lower=0> alpha;
  vector<lower=0>[D] rho;
  real<lower=0> sigma;
}

model {
  vector[N] mu = H * beta;
  matrix[N, N] K = cov_ard_sqexp(X, rho, alpha, jitter)
                   + diag_matrix(rep_vector(square(sigma), N));
  matrix[N, N] L_K = cholesky_decompose(K);

  beta  ~ normal(0, 1);
  alpha ~ normal(0, 1.5);
  rho   ~ lognormal(0, 1);
  sigma ~ normal(0, 0.5);
  y ~ multi_normal_cholesky(mu, L_K);
}

generated quantities {
  vector[N_new] y_new;
  if (N_new > 0) {
    matrix[N, N] K = cov_ard_sqexp(X, rho, alpha, jitter)
                     + diag_matrix(rep_vector(square(sigma), N));
    matrix[N, N] L_K = cholesky_decompose(K);
    matrix[N, N_new] K_x_xnew = cross_cov_ard(X, X_new, rho, alpha);
    matrix[N_new, N_new] K_new = cov_ard_sqexp(X_new, rho, alpha, jitter);
    vector[N] resid = y - (H * beta);

    vector[N] alpha_vec = mdivide_left_tri_low(L_K, resid);
    alpha_vec = mdivide_left_tri_low(L_K', alpha_vec);

    vector[N_new] f_mean = (K_x_xnew' * alpha_vec);
    matrix[N, N_new] v = mdivide_left_tri_low(L_K, K_x_xnew);
    vector[N_new] f_var = to_vector(diagonal(K_new)) - to_vector(columns_dot_self(v));
    for (m in 1:N_new) {
      real m_mean = (H_new[m] * beta) + f_mean[m];
      real m_sd = sqrt(f_var[m] + square(sigma));
      y_new[m] = normal_rng(m_mean, m_sd);
    }
  }
}
'''


def load_data():
    train_X = pd.read_csv(BASE / "train_X.csv").to_numpy(dtype=float)
    train_y = pd.read_csv(BASE / "train_y.csv")["y"].to_numpy(dtype=float)
    test_X = pd.read_csv(BASE / "test_X.csv").to_numpy(dtype=float)
    with (BASE / "meta_public.json").open(encoding="utf-8") as handle:
        meta = json.load(handle)

    P = int(meta["P"])
    jitter = float(meta["jitter"])
    N, D = train_X.shape
    N_new = test_X.shape[0]
    H = np.column_stack((np.ones(N), train_X[:, 0], train_X[:, 1]))
    H_new = np.column_stack((np.ones(N_new), test_X[:, 0], test_X[:, 1]))

    if P != H.shape[1]:
        raise ValueError(f"Expected P={H.shape[1]} from the R design matrix, got {P}")

    return {
        "N": N,
        "D": D,
        "X": train_X,
        "P": P,
        "H": H,
        "y": train_y,
        "jitter": jitter,
        "N_new": N_new,
        "X_new": test_X,
        "H_new": H_new,
    }


def save_numeric(path, values):
    np.savetxt(path, np.asarray(values, dtype=float).reshape(-1), fmt="%.17g")


def main():
    data = load_data()
    posterior = stan.build(STAN_CODE, data=data, random_seed=1)
    fit = posterior.sample(
        num_chains=4,
        num_samples=1000,
        num_warmup=1000,
        num_thin=2,
        save_warmup=False,
        init_radius=0.1,
        refresh=200,
        delta=0.93,
        max_depth=14,
        gamma=0.05,
        kappa=0.75,
        t0=10,
        init_buffer=100,
        term_buffer=50,
        window=25,
    )

    alpha_mean = np.asarray(fit["alpha"], dtype=float).mean()
    sigma_mean = np.asarray(fit["sigma"], dtype=float).mean()
    rho_mean = np.asarray(fit["rho"], dtype=float).mean(axis=1)
    beta_mean = np.asarray(fit["beta"], dtype=float).mean(axis=1)

    save_numeric(BASE / "alpha_est.csv", alpha_mean)
    save_numeric(BASE / "sigma_est.csv", sigma_mean)
    save_numeric(BASE / "rho_est.csv", rho_mean)
    save_numeric(BASE / "beta_est.csv", beta_mean)

    print("Posterior means:")
    print("alpha:", alpha_mean)
    print("sigma:", sigma_mean)
    print("rho:  ", *rho_mean)
    print("beta: ", *beta_mean)


if __name__ == "__main__":
    main()

